INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(54411, 'Deuteronomy 3:2', 'Deuteronomy', 3, 2, 'خو څښتن ماته وویل: ‹د هغه څخه مه وېرېږه. زه هغه، د هغه کسان او د هغه ټوله سیمه تاته درکوم. د هغه سره هماغه شان چلند وکړه لکه څنګه چې دې د اموریانو د پاچا سیحون سره چې حشبون یې پایتخت ؤ کړی ؤ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_2.mp3', '', 1761754199, 1761754199),
(54412, 'Deuteronomy 3:3', 'Deuteronomy', 3, 3, 'نو څښتن عوج پاچا او د هغه لښکر هم مونږ ته په لاس راکړ او هغوی ټول مو ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_3.mp3', '', 1761754199, 1761754199),
(54413, 'Deuteronomy 3:4', 'Deuteronomy', 3, 4, 'په همدې وخت کې مونږ د هغه ټول ښارونه ونیول، یو ښار هم زمونږ څخه پاتې نه شو. ټول ښارونه چې مونږ ونیول شمېر یې شپېتو ته رسېده، یعنې د ارجوب ټوله سیمه چې د باشان پاچا عوج ورباندې حکومت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_4.mp3', '', 1761754199, 1761754199),
(54414, 'Deuteronomy 3:5', 'Deuteronomy', 3, 5, 'دغو ټولو ښارونو لوړ دېوالونه او داسې دروازې درلودلې چې په سیخونو باندې بندېدلې. همدارنګه ډېر داسې کلي هم وو چې دېوالونه یې نه درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_5.mp3', '', 1761754199, 1761754199),
(54415, 'Deuteronomy 3:6', 'Deuteronomy', 3, 6, 'مونږ ټول ښارونه وران کړل او ټول نارینه، ښځې او ماشومان مو ووژل. مونږ د حشبون پاچا سیحون په ښارونو کې هم همداسې کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_6.mp3', '', 1761754199, 1761754199),
(54416, 'Deuteronomy 3:7', 'Deuteronomy', 3, 7, 'مونږ حیوانات یووړل او ښارونه مو لوټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_7.mp3', '', 1761754199, 1761754199),
(54417, 'Deuteronomy 3:8', 'Deuteronomy', 3, 8, 'په هغه وخت کې مونږ د اردن د سیند په ختیځ کې د هغو دوو اموریایي پاچاهانو څخه د ارنون د سیند څخه د حرمون تر غره پورې ځمکه ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_8.mp3', '', 1761754199, 1761754199),
(54418, 'Deuteronomy 3:9', 'Deuteronomy', 3, 9, 'صیدونیان د حرمون غر د سریون په نوم یادوي او اموریان یې د سنیر په نوم یادوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_9.mp3', '', 1761754199, 1761754199),
(54419, 'Deuteronomy 3:10', 'Deuteronomy', 3, 10, 'مونږ د باشان د پاچا عوج ټوله سیمه ونیوله یعنې هغه ښارونه چې په لوړه جلګه باندې وو او د سلخه او ادرعي د ښارونو تر ختیځ پورې د جلعاد او باشان سیمې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_10.mp3', '', 1761754199, 1761754199),
(54420, 'Deuteronomy 3:11', 'Deuteronomy', 3, 11, 'عوج پاچا په رفاییانو کې اخرنی کس ؤ. د معیاري اندازې له مخې د هغه تابوت چې د تیږو څخه جوړ شوی ؤ، څلور متره اوږد ؤ او نژدې دوه متره پلن ؤ. هغه تر اوسه پورې د عمونیانو د ربه په ښار کې شته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_11.mp3', '', 1761754199, 1761754199),
(54421, 'Deuteronomy 3:12', 'Deuteronomy', 3, 12, 'کله چې مونږ هغه ځمکه ونیوله، ما د روبین او جاد قبیلو ته هغه سیمه ورکړه چې د عروعیر د ښار په شمال کې وه (د عروعیر ښار د ارنون سیند ته نژدې ؤ) او د جلعاد د غرنۍ سیمې یوه برخه مې هم د هغه ځای د ښارونو سره ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_12.mp3', '', 1761754199, 1761754199),
(54422, 'Deuteronomy 3:13', 'Deuteronomy', 3, 13, 'پاتې جلعاد او ټول باشان چې عوج ورباندې حکومت کړی ؤ یعنې د ټول ارجوب سیمه مې هم د منسي نیمې قبیلې ته ورکړه. باشان د رفاییانو د هېواد په نوم یادېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_13.mp3', '', 1761754199, 1761754199),
(54423, 'Deuteronomy 3:14', 'Deuteronomy', 3, 14, 'یاییر چې د منسي د قبیلې څخه ؤ، هغه د ارجوب ټوله سیمه یعنې د باشان سیمه د جشور او معکې تر سرحده پورې ونیوله. د هغې سیمې کلي یې په خپل نوم یاد کړل او تر اوسه پورې د یاییر د کلیو په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_14.mp3', '', 1761754199, 1761754199),
(54424, 'Deuteronomy 3:15', 'Deuteronomy', 3, 15, 'جلعاد مې د ماخیر طایفې ته چې د منسي د قبیلې څخه ده، ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_15.mp3', '', 1761754199, 1761754199),
(54425, 'Deuteronomy 3:16', 'Deuteronomy', 3, 16, 'د روبین او جاد قبیلو ته مې د جلعاد څخه د ارنون تر سینده پورې سیمه ورکړه. هغه سیند د هغوی جنوبي سرحد ؤ او د یبوق سیند د هغوی شمالي سرحد ؤ. د یبوق د سیند یوه برخه د عمونیانو سرحد ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_16.mp3', '', 1761754199, 1761754199),
(54426, 'Deuteronomy 3:17', 'Deuteronomy', 3, 17, 'د لوېدیځې خوا څخه د هغوی سیمه د اردن تر سیند پورې یعنې د جلیل د بحیرې څخه تر مړې بحیرې او د پیسګاه د غره تر لمنې پورې غزېدلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_17.mp3', '', 1761754199, 1761754199),
(54427, 'Deuteronomy 3:18', 'Deuteronomy', 3, 18, 'په همدې وخت کې ما هغوی ته دا امر وکړ: ‹زمونږ څښتن خدای تاسو ته دا ځمکه د اردن په ختیځ کې درکړې ده چې ویې نیسئ. نو اوس خپلو جنګي کسانو ته وسلې ورکړئ او د اسراییلو د نورو قبیلو څخه یې مخکې د اردن بلې غاړې ته ولېږئ چې د هغوی سره د هغوی د ځمکې په نیولو کې مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_18.mp3', '', 1761754199, 1761754199),
(54428, 'Deuteronomy 3:19', 'Deuteronomy', 3, 19, 'خو ستاسو ښځې، ماشومان او همدارنګه ستاسو حیوانات به چې ډېر زیات دي، په هغو ښارونو کې پاتې کیږي چې ما تاسو ته درکړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_19.mp3', '', 1761754199, 1761754199),
(54429, 'Deuteronomy 3:20', 'Deuteronomy', 3, 20, 'کله چې څښتن ستاسو په شان نورو اسراییلیانو ته ارامي ور په برخه کړي او کله چې هغوی هغه ځمکه ونیسي چې څښتن یې ورته د اردن د سیند په بله غاړه باندې ورکوي، نو بیا تاسو کولای شئ بېرته دې ځمکې ته چې تاسو ته مې درکړې ده، راستانه شئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_20.mp3', '', 1761754199, 1761754199),
(54430, 'Deuteronomy 3:21', 'Deuteronomy', 3, 21, 'بیا مې یوشع ته داسې حکم وکړ: ‹تا هغه ټول کارونه په خپلو سترګو لیدلي دي چې زمونږ څښتن خدای په هغو دوو پاچاهانو یعنې سیحون او عوج باندې وکړل. هغه به د هغو نورو ټولو خلکو سره هم همداسې وکړي چې ته یې په وطن باندې حمله کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_21.mp3', '', 1761754199, 1761754199),
(54431, 'Deuteronomy 3:22', 'Deuteronomy', 3, 22, 'د هغوی څخه مه وېرېږئ، ځکه چې زمونږ څښتن خدای به ستاسو دپاره وجنګیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_22.mp3', '', 1761754199, 1761754199),
(54432, 'Deuteronomy 3:23', 'Deuteronomy', 3, 23, 'په هغه وخت کې ما داسې زارۍ وکړې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_23.mp3', '', 1761754199, 1761754199),
(54433, 'Deuteronomy 3:24', 'Deuteronomy', 3, 24, '‹څښتن تعالی، زه پوهېږم چې تا ماته یوازې د خپلې لویۍ او قدرت څرګندول پیل کړل. په اسمان کې او په ځمکه باندې هېڅ داسې خدای نشته چې داسې لوی لوی کارونه وکولای شي چې تا کړي دي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_24.mp3', '', 1761754199, 1761754199),
(54434, 'Deuteronomy 3:25', 'Deuteronomy', 3, 25, 'څښتنه، ما پرېږده چې د اردن د سیند څخه تېر شم او هغه حاصلخېزه ځمکه ووینم چې په بله غاړه باندې پرته ده او ښایسته غرنۍ سیمه او د لبنان غرونه ووینم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_25.mp3', '', 1761754199, 1761754199),
(54435, 'Deuteronomy 3:26', 'Deuteronomy', 3, 26, 'خو څښتن ستاسو په خاطر په ما باندې په قهر ؤ او ماته یې غوږ نه نیوه. د دې په ځای هغه وویل: ‹بس کړه! بیا د دې خبرې یادونه ونه کړې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_26.mp3', '', 1761754199, 1761754199),
(54436, 'Deuteronomy 3:27', 'Deuteronomy', 3, 27, 'د پیسګاه د غره څوکې ته وخېژه او د شمال او جنوب، ختیځ او لوېدیځ خواته وګوره. څه چې درته ښکاري هغه په غور سره وګوره، ځکه چې ته به هېڅکله د اردن د سیند څخه تېر نه شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_27.mp3', '', 1761754199, 1761754199),
(54437, 'Deuteronomy 3:28', 'Deuteronomy', 3, 28, 'یوشع ته لارښوونې وکړه. د هغه عزم قوي کړه، ځکه چې هغه به خلک بلې غاړې ته پورې باسي چې هغه ځمکه ونیسي چې ته یې وینې.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_28.mp3', '', 1761754199, 1761754199),
(54438, 'Deuteronomy 3:29', 'Deuteronomy', 3, 29, 'نو مونږ په هغې درې کې پاتې شو چې د بیت فغور ښار ته مخامخ وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy3_verse_29.mp3', '', 1761754199, 1761754199),
(54439, 'Isaiah 8:1', 'Isaiah', 8, 1, 'څښتن ماته وویل: «یوه لویه تخته راواخله او په هغې باندې په غټو ټکو ولیکه: ‹مهیر شلال حاش بز.› یعنې مال به زر لوټ شي او شتمني به په چټکۍ سره په غنیمت ونیول شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_1.mp3', '', 1761754199, 1761754199),
(54440, 'Isaiah 8:2', 'Isaiah', 8, 2, 'ما دوه اعتباري کسان چې یو یې اوریا کاهن او بل یې زکریا د یبرکیا زوی دی، راوغوښتل چې شاهدان اوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_2.mp3', '', 1761754199, 1761754199),
(54441, 'Isaiah 8:3', 'Isaiah', 8, 3, 'څه موده وروسته زما پیغمبره ښځه امیدواره شوه او زوی یې پیدا شو. څښتن ماته وویل: «په هغه باندې د ‹مال به زر لوټ شي او شتمني به په چټکۍ سره په غنیمت ونیول شي› نوم کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_3.mp3', '', 1761754199, 1761754199),
(54442, 'Isaiah 8:4', 'Isaiah', 8, 4, 'مخکې له دې چې ماشوم وکولای شي ‹مور› او ‹پلار› ووایي، د اشور امپراتور به د دمشق ټوله شتمني او د سامرې ټول غنیمت له ځان سره یوسي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_4.mp3', '', 1761754199, 1761754199),
(54443, 'Isaiah 8:5', 'Isaiah', 8, 5, 'څښتن یوځل بیا ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_5.mp3', '', 1761754199, 1761754199),
(54444, 'Isaiah 8:6', 'Isaiah', 8, 6, '«په دې خاطر چې د یهودا خلکو د شیلوخ د ویالې هغه اوبه چې په ارامۍ سره جاري دي بې ارزښته وګڼلې او د رزین او د فقح پاچاهانو سره خوشحاله دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_6.mp3', '', 1761754199, 1761754199),
(54445, 'Isaiah 8:7', 'Isaiah', 8, 7, 'نو ځکه زه څښتن به د اشور امپراتور او د هغه ټولې لښکرې راولم چې په یهودا باندې حمله وکړي. هغوی به د فرات د سیند د سېلاب په شان چې اوبه یې د غاړو نه اووښتې وي، حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_7.mp3', '', 1761754199, 1761754199),
(54446, 'Isaiah 8:8', 'Isaiah', 8, 8, 'هغوی به د سېلاب په شان له یهودا نه تېر شي، لکه د سیند په شان به له څنډو نه واوړي او خلک به تر ستوني پورې پټ کړي.» خو خدای زمونږ سره مل دی او لکه د مرغۍ په شان به په خپلو خپرو ورو وزرونو هغه وطن وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_8.mp3', '', 1761754199, 1761754199),
(54447, 'Isaiah 8:9', 'Isaiah', 8, 9, 'ای قومونو، یوځای راغونډ شئ او ووېرېږئ! ای لېرې هېوادونو، د جګړې دپاره تیار شئ خو تاسو به ټوټې ټوټې شئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_9.mp3', '', 1761754199, 1761754199),
(54448, 'Isaiah 8:10', 'Isaiah', 8, 10, 'خپلې نقشې جوړې کړئ! خو هغه به هېڅکله بریالي نه شي. څومره خبرې چې غواړئ ویې کړئ! خو هغه ټولې به بې ګټې وي، ځکه چې خدای زمونږ سره مل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_10.mp3', '', 1761754199, 1761754199),
(54449, 'Isaiah 8:11', 'Isaiah', 8, 11, 'خدای زه ټینګ ونیولم او ماته یې خبرداری راکړ چې په هغې لارې باندې به نه ځې په کومه چې دغه خلک ځي، هغه وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_11.mp3', '', 1761754199, 1761754199),
(54450, 'Isaiah 8:12', 'Isaiah', 8, 12, '«هره خبره دسیسه مه ګڼئ څرنګه چې دغه خلک فکر کوي او له هغو شیانو چې هغوی وېریږي تاسو مه وېرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_12.mp3', '', 1761754199, 1761754199),
(54451, 'Isaiah 8:13', 'Isaiah', 8, 13, 'باید پوه شئ چې زه مطلق قادر څښتن، سپېڅلی یم. تاسو زما درناوی وکړئ او زما نه ووېرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_13.mp3', '', 1761754199, 1761754199),
(54452, 'Isaiah 8:14', 'Isaiah', 8, 14, 'څښتن به ستاسو دپاره یو پناه ځای وي. هغه به د اسراییلو او د یهودا دپاره د یوې داسې تیږې په شان وي چې خلک ورباندې راغورځیږي، لکه ګټ چې ورباندې رالویږي. هغه به د اورشلیم د خلکو د راګېرېدلو دپاره یو دام وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_14.mp3', '', 1761754199, 1761754199),
(54453, 'Isaiah 8:15', 'Isaiah', 8, 15, 'ډېر به ورباندې راوغورځیږي، هغوی به راولویږي او ټوټې ټوټې به شي. هغوی به په دام کې راګېر شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_15.mp3', '', 1761754199, 1761754199),
(54454, 'Isaiah 8:16', 'Isaiah', 8, 16, 'هغه تعلیم چې خدای ماته راکړی دی، هغه په یو طومار کې ولیکل شي او بیا به وتړل شي او مهر به شي، وروسته به زما شاګردانو ته ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_16.mp3', '', 1761754199, 1761754199),
(54455, 'Isaiah 8:17', 'Isaiah', 8, 17, 'څښتن خپل ځان د یعقوب د قوم څخه پټ کړی دی، خو زه به په صبر سره هغه ته انتظار وباسم او هغه ته هیله من یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_17.mp3', '', 1761754199, 1761754199),
(54456, 'Isaiah 8:18', 'Isaiah', 8, 18, 'ګورئ زه د خپلو اولادونو سره چې څښتن ماته راکړي دي، مطلق قادر څښتن چې تخت یې د صهیون په غره باندې دی، هغه مونږ د نښو او خبرداریو په توګه د اسراییلو خلکو ته رالېږلي یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_18.mp3', '', 1761754199, 1761754199),
(54457, 'Isaiah 8:19', 'Isaiah', 8, 19, 'خو خلک به تاسو ته ووایي چې د فال کتونکو او جادوګرانو سره چې چوف چوف کوي مشوره او پوښتنه وکړئ. هغوی به وایي: «ایا خلک د خپلو خدایانو سره مشوره نه کوي؟ خلک باید د ارواح ګانو څخه د ژوندیو دپاره مشوره او لارښوونه وغواړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_19.mp3', '', 1761754199, 1761754199),
(54458, 'Isaiah 8:20', 'Isaiah', 8, 20, 'د څښتن تعلیم او حکمونو ته پام وکړئ! که د دې کلام له مخې خبرې ونه کړي، نو د هغوی دپاره د سهار رڼا نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_20.mp3', '', 1761754199, 1761754199),
(54459, 'Isaiah 8:21', 'Isaiah', 8, 21, 'په ټول وطن کې به خلک ډېر ناامیده، وږي او سرګردانه ګرځي. له لوږې او غوسې به خپل پاچا او خدای ته ښکنځلې کوي. هغوی به اسمان ته ګوري،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_21.mp3', '', 1761754199, 1761754199),
(54460, 'Isaiah 8:22', 'Isaiah', 8, 22, 'یا به ځمکې ته ګوري، خو پرته له تکلیفه او تورې تیارې څخه به بل هېڅ نه ویني او په تکه توره تیاره کې به وغورځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah8_verse_22.mp3', '', 1761754199, 1761754199),
(54461, 'Isaiah 38:1', 'Isaiah', 38, 1, 'په هغو ورځو کې حزقیا پاچا ناروغ شو او مرګ ته نژدې ؤ. د آموص زوی اشعیا نبي ورغی چې هغه وویني او هغه ته یې وویل: «څښتن داسې وایي چې خپل ټول کارونه دې برابر کړه، ځکه چې ته مړ کېږې او روغ به نه شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_1.mp3', '', 1761754199, 1761754199),
(54462, 'Isaiah 38:2', 'Isaiah', 38, 2, 'حزقیا خپل مخ دېوال ته واړاوه او دعا یې وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_2.mp3', '', 1761754199, 1761754199),
(54463, 'Isaiah 38:3', 'Isaiah', 38, 3, '«ای څښتنه، دا در په یاد کړه چې ما د زړه له کومي ستا خدمت کړی دی، تاته وفادار وم او تل مې دا کوښښ کړی دی چې هغه کار وکړم چې تا راڅخه غوښتنه کړې ده.» بیا یې ډېر سخت وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_3.mp3', '', 1761754199, 1761754199),
(54464, 'Isaiah 38:4', 'Isaiah', 38, 4, 'بیا څښتن اشعیا ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_4.mp3', '', 1761754199, 1761754199),
(54465, 'Isaiah 38:5', 'Isaiah', 38, 5, '«لاړ شه او حزقیا ته ووایه: ‹ستا د نیکه داود څښتن خدای داسې وایي: ما ستا دعا قبوله کړه او ستا اوښکې مې ولیدلې. زه به ستا ژوند پنځلس کاله نور هم زیات کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_5.mp3', '', 1761754199, 1761754199),
(54466, 'Isaiah 38:6', 'Isaiah', 38, 6, 'زه به تا او دغه ښار د اشور د پاچا له لاسه وژغورم او د دې ښار څخه به دفاع وکړم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_6.mp3', '', 1761754199, 1761754199),
(54467, 'Isaiah 38:7', 'Isaiah', 38, 7, 'بیا اشعیا، حزقیا ته وویل: «څښتن د دې وعدې د ثبوت دپاره دا نښه تاته درکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_7.mp3', '', 1761754199, 1761754199),
(54468, 'Isaiah 38:8', 'Isaiah', 38, 8, 'څښتن به د احاز په زینه باندې د لمر سیوری لس پوړۍ وروسته کړي.» نو سیوری بېرته لس پوړۍ وروسته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_8.mp3', '', 1761754199, 1761754199),
(54469, 'Isaiah 38:9', 'Isaiah', 38, 9, 'کله چې حزقیا له ناروغۍ نه روغ شو، نو هغه دا شکرګزاري ولیکله:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_9.mp3', '', 1761754199, 1761754199),
(54470, 'Isaiah 38:10', 'Isaiah', 38, 10, 'ما کاوه فکر چې د ځوانۍ په عمر باید لاړ شمه د مړو دنیا ته او شم به محروم له پاتې کلونو د ژوند', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_10.mp3', '', 1761754199, 1761754199),
(54471, 'Isaiah 38:11', 'Isaiah', 38, 11, 'ما کاوه فکر چې په نړۍ کې د ژوندیو به هېڅکله څښتن ونه وینم او نه به ووینمه هغه انسان چې اوسیږي دې نړۍ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_11.mp3', '', 1761754199, 1761754199),
(54472, 'Isaiah 38:12', 'Isaiah', 38, 12, 'د ژوند مزي مې پرې کیږي لکه کېږدۍ د شپون چې راټولیږي لکه څنګه چې ټوکر راټولوي اوبدونکی ما راټول کړلو خپل ژوند او لکه پرې کیږي چې ټوکر د اوبدلو د کارګاه نه ما کاوه فکر چې څښتن مې رسوي ژوند پای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_12.mp3', '', 1761754199, 1761754199),
(54473, 'Isaiah 38:13', 'Isaiah', 38, 13, 'ما ټوله شپه کولو فکر لکه داسې چې زمری مې ټول هډوکي ماتوي ما کاوه فکر چې څښتن مې رسوي ژوند پای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_13.mp3', '', 1761754199, 1761754199),
(54474, 'Isaiah 38:14', 'Isaiah', 38, 14, 'زما اواز دی نری شوی توتکۍ په شان کول زګېروي مې د کوترې په شان زما سترګې ستړې شوې دي اسمان ته په کتلو ای څښتنه، په ما ظلم کیږي، راسره مرسته وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_14.mp3', '', 1761754199, 1761754199),
(54475, 'Isaiah 38:15', 'Isaiah', 38, 15, 'خو څه چاره لرم زه؟ ځکه څښتن راسره کړې دي خبرې او دا دی کار د هغه ژوند مې دی تریخ او خوب مې الوتی دی له سترګو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_15.mp3', '', 1761754199, 1761754199),
(54476, 'Isaiah 38:16', 'Isaiah', 38, 16, 'ای څښتنه، ستا کلام او ستا کارونه ورکوي هرچا ته ژوند او ماته هم ماته روغتیا راکړه او نوی ژوند راته په برخه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_16.mp3', '', 1761754199, 1761754199),
(54477, 'Isaiah 38:17', 'Isaiah', 38, 17, 'په رښتیا کوم کړاوونه چې زغملي دي ما هغه په ګټه وو زما ستا مینې وژغورلم د مرګ له کندې ځکه دې وغورځول له نظره ګناهونه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_17.mp3', '', 1761754199, 1761754199),
(54478, 'Isaiah 38:18', 'Isaiah', 38, 18, 'څوک چې قبرونو کې دي شکرګزاري د ستا کولای نه شي مړي ویلی نه شي ستا ثنا او په وفادارۍ دې نه کوي باور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_18.mp3', '', 1761754199, 1761754199),
(54479, 'Isaiah 38:19', 'Isaiah', 38, 19, 'شکرګزاري کوي ستا، ژوندي کسان یوازې لکه څنګه چې یې زه کوم نن پلرونه وایي اولادونو ته خپل چې ته څومره وفادار یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_19.mp3', '', 1761754199, 1761754199),
(54480, 'Isaiah 38:20', 'Isaiah', 38, 20, 'څښتن ژغورلی یمه ربابونه به وهو او په سندرو به دې وایو ثنا ترڅو ژوندي یو مونږ به وکړو دا کار ستا په کور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_20.mp3', '', 1761754199, 1761754199),
(54481, 'Isaiah 38:21', 'Isaiah', 38, 21, 'نو اشعیا د حزقیا خدمتګارانو ته ویلي وو: «د انځرو مرهم واخلئ او هغه د پاچا په دانه باندې کېږدئ چې روغ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_21.mp3', '', 1761754199, 1761754199),
(54482, 'Isaiah 38:22', 'Isaiah', 38, 22, 'حزقیا پوښتنه کړې وه: «هغه به کومه نښه وي چې وکولای شم د څښتن کور ته لاړ شم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah38_verse_22.mp3', '', 1761754199, 1761754199),
(54483, 'Judges 18:1', 'Judges', 18, 1, 'په هغې زمانه کې اسراییلو پاچا نه درلود. د دان قبیلې یو ځای لټاوه چې په کې واوسیږي، ځکه چې هغوی لا تر هغه وخته پورې د اسراییلو د قبیلو په منځ کې خپله ځمکه تر لاسه کړې نه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_1.mp3', '', 1761754199, 1761754199),
(54484, 'Judges 18:2', 'Judges', 18, 2, 'نو د دان د قبیلې خلکو د خپلو طایفو څخه پنځه تنه جنګي کسان د زرعه او اشتاول څخه ولېږل چې د هغې خاورې وضع وڅېړي چې هغوی غوښتل په کې واوسیږي. کله چې هغه کسان د افرایم غرنۍ سیمې ته ورسېدل، نو د میخا کور ته راغلل او هلته یې شپه تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_2.mp3', '', 1761754199, 1761754199),
(54485, 'Judges 18:3', 'Judges', 18, 3, 'هغوی په هغه ځای کې د ځوان لاوي لهجه وپېژندله، نو هغوی ورغلل او پوښتنه یې ترې وکړه: «ته دلته څه کوې؟ چا دلته راوستلی یې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_3.mp3', '', 1761754199, 1761754199),
(54486, 'Judges 18:4', 'Judges', 18, 4, 'هغه ځواب ورکړ: «ما د میخا سره یو قرارداد کړی دی او هغه ماته د کاهنتوب د خدمت په بدل کې اجوره راکوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_4.mp3', '', 1761754199, 1761754199),
(54487, 'Judges 18:5', 'Judges', 18, 5, 'بیا هغوی ورته وویل: «مهرباني وکړه د خدای څخه سوال وکړه چې مونږ به په دې سفر کې بریالي شو که نه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_5.mp3', '', 1761754199, 1761754199),
(54488, 'Judges 18:6', 'Judges', 18, 6, 'کاهن هغوی ته په ځواب کې وویل: «په خیر لاړ شئ، څښتن به تاسو په دې سفر کې وساتي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_6.mp3', '', 1761754199, 1761754199),
(54489, 'Judges 18:7', 'Judges', 18, 7, 'نو هغه پنځه کسان روان شول او د لایش ښار ته لاړل. هغوی ولیدل چې د هغه ځای خلک د صیدونیانو په شان په سوله او امن کې ژوند کوي. هغوی ارام خلک وو او په خاطر جمعۍ سره یې ژوند تېراوه. د هغوی سره د هېڅ شي کمی نه ؤ. هغوی د صیدونیانو څخه لېرې اوسېدل او د بل چا سره یې معامله نه درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_7.mp3', '', 1761754199, 1761754199),
(54490, 'Judges 18:8', 'Judges', 18, 8, 'کله چې هغه کسان بېرته زرعه او اشتاول ته راستانه شول، نو خلکو ورڅخه پوښتنه وکړه چې «تاسو څه خبر راوړی دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_8.mp3', '', 1761754199, 1761754199),
(54491, 'Judges 18:9', 'Judges', 18, 9, 'هغوی په ځواب کې وویل: «راځئ چې په لایش باندې حمله وکړو. مونږ هغه ځمکه ولیدله، هغه ډېره ښه ځمکه ده. زړه نازړه کېږئ مه! لاړ شئ او هغه ونیسئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_9.mp3', '', 1761754199, 1761754199),
(54492, 'Judges 18:10', 'Judges', 18, 10, 'کله چې هلته ورسېدلئ، تاسو به ووینئ چې هغه بې غمه خلک دي. هغه یو لوی وطن دی هرڅه چې وغواړئ هلته شته او خدای هغه تاسو ته درکړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_10.mp3', '', 1761754199, 1761754199),
(54493, 'Judges 18:11', 'Judges', 18, 11, 'نو د دان د قبیلې څخه شپږ سوه تنه د جګړې دپاره تیار شول او د زرعه او اشتاول څخه روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_11.mp3', '', 1761754199, 1761754199),
(54494, 'Judges 18:12', 'Judges', 18, 12, 'هغوی لاړل او د یهودا د قریت یعاریم د ښار په لوېدیځ کې یې خېمې ودرولې. په دې خاطر هغه ځای تر نن ورځې پورې د دان د کمپ په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_12.mp3', '', 1761754199, 1761754199),
(54495, 'Judges 18:13', 'Judges', 18, 13, 'بیا هغوی د هغه ځای څخه لاړل او د میخا کور ته چې د افرایم په غرنۍ سیمه کې ؤ، ورغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_13.mp3', '', 1761754199, 1761754199),
(54496, 'Judges 18:14', 'Judges', 18, 14, 'هغو پنځو کسانو چې د لایش خاوره یې کتلې وه، خپلو ملګرو ته وویل: «ایا تاسو پوهېږئ چې د دغو کورونو څخه په یو کور کې د لرګیو بت دی چې د سپینو زرو پوښ ورته ورکړل شوی دی؟ هلته نور بتان او سپېڅلی پېشبند هم شته. تاسو څه فکر کوئ چې څه باید وکړو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_14.mp3', '', 1761754199, 1761754199),
(54497, 'Judges 18:15', 'Judges', 18, 15, 'نو هغوی د میخا کور ته چې هغه ځوان لاوي په کې اوسېده، ننوتل او د هغه لاوي څخه یې د هغه د احوال پوښتنه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_15.mp3', '', 1761754199, 1761754199),
(54498, 'Judges 18:16', 'Judges', 18, 16, 'په دې وخت کې د دان شپږ سوه عسکر چې په وسلو باندې سمبال وو، د دروازې په خوله کې ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_16.mp3', '', 1761754199, 1761754199),
(54499, 'Judges 18:17', 'Judges', 18, 17, 'په داسې حال کې چې کاهن د شپږ سوه وسله والو کسانو سره د دروازې په خوله کې ولاړ ؤ، هغه پنځه جاسوسان دننه ننوتل او په سپینو زرو باندې پوښل شوی بت، نور بتان او سپېڅلی پېشبند یې راواخیستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_17.mp3', '', 1761754199, 1761754199),
(54500, 'Judges 18:18', 'Judges', 18, 18, 'کله چې کاهن ولیدل چې دا کسان سپېڅلي شیان وړي، نو د هغوی څخه یې پوښتنه وکړه: «تاسو څه کوئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_18.mp3', '', 1761754199, 1761754199),
(54501, 'Judges 18:19', 'Judges', 18, 19, 'هغوی وویل: «غلی شه! خوله دې بنده کړه! زمونږ سره راځه او زمونږ کاهن او مشاور شه. تاته کومه خبره ښه ښکاري، چې د یو کس د کورنۍ کاهن شې او که د اسراییلو د یوې قبیلې کاهن شې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_19.mp3', '', 1761754199, 1761754199),
(54502, 'Judges 18:20', 'Judges', 18, 20, 'په دې خبره کاهن ډېر خوشحاله شو. نو هغه سپېڅلي شیان واخیستل او د هغوی سره لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_20.mp3', '', 1761754199, 1761754199),
(54503, 'Judges 18:21', 'Judges', 18, 21, 'هغوی خپل ماشومان، حیوانات او خپله شتمني مخکې کړل او په خپله لاره روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_21.mp3', '', 1761754199, 1761754199),
(54504, 'Judges 18:22', 'Judges', 18, 22, 'کله چې هغوی د میخا د کور څخه یو څه لېرې لاړل، نو میخا خپل ګاونډیان د جګړې دپاره راوغوښتل او هغوی د دان د کسانو پسې روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_22.mp3', '', 1761754199, 1761754199),
(54505, 'Judges 18:23', 'Judges', 18, 23, 'څنګه چې هغوی ته ورورسېدل، نو غږ یې ورباندې وکړ چې ودریږي. د دان کسان راوګرځېدل او د میخا څخه یې پوښتنه وکړه: «څه خبره ده؟ دا کسان دې ولې راټول کړي دي او مونږ تعقیبوې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_23.mp3', '', 1761754199, 1761754199),
(54506, 'Judges 18:24', 'Judges', 18, 24, 'میخا په ځواب کې وویل: «تاسو زما کاهن او هغه خدایان چې ما جوړ کړي وو، یووړل. هېڅ شی مو راته نه دی پریښی. بیا څنګه زما څخه پوښتنه کوئ چې څه خبره ده؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_24.mp3', '', 1761754199, 1761754199),
(54507, 'Judges 18:25', 'Judges', 18, 25, 'د دان سړیو په ځواب کې وویل: «زمونږ سره بحث مه کوه، هسې نه چې زمونږ ځینې بد خویه کسان درباندې حمله وکړي او ته او ستا کورنۍ به ووژل شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_25.mp3', '', 1761754199, 1761754199),
(54508, 'Judges 18:26', 'Judges', 18, 26, 'نو بیا د دان سړي په خپله لاره روان شول. میخا ولیدل چې هغوی ورباندې ډېر قوي دي، نو هغه بېرته خپل کور ته ستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_26.mp3', '', 1761754199, 1761754199),
(54509, 'Judges 18:29', 'Judges', 18, 29, 'د هغه ښارګوټي نوم یې د لایش څخه په دان باندې بدل کړ، یعنې د یعقوب د زامنو څخه د یو زوی په نوم چې د هغوی د قبیلې نیکه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_29.mp3', '', 1761754199, 1761754199),
(54510, 'Judges 18:30', 'Judges', 18, 30, 'د دان سړیو د خپلو ځانونو دپاره د میخا بت ودراوه او یوناتان د جرشون زوی او د موسی لمسي د دان د قبیلې دپاره د کاهن په توګه خدمت کاوه. د هغه اولادې تر هغې پورې د کاهنانو په توګه خدمت کاوه، ترڅو چې هغه خلک جلاوطنه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges18_verse_30.mp3', '', 1761754199, 1761754199);